mapper.select:
SELECT COUNT(*)
FROM api_key
WHERE last_used_at >= #{start}

SELECT cl.key_id AS "keyId", COALESCE(k.name, '(deleted)') AS "name", COUNT(*) AS "count", COALESCE(SUM(cl.prompt_tokens), 0) AS "prompt", COALESCE(SUM(cl.completion_tokens), 0) AS "completion", COALESCE(SUM(cl.total_tokens), 0) AS "total", COALESCE(SUM(cl.cached_tokens), 0) AS "cached", AVG(cl.tokens_per_sec) AS "avgSpeed", AVG(cl.duration_ms) AS "avgDuration", SUM(CASE WHEN cl.status_code IS NOT NULL AND cl.status_code >= 400 THEN 1 ELSE 0 END) AS "errors" FROM call_log cl LEFT JOIN api_key k ON k.id = cl.key_id WHERE 1 = 1
AND cl.key_id = #{keyId}
AND cl.started_at >= #{start}
AND cl.started_at < #{end}
GROUP BY cl.key_id, k.name ORDER BY "count" DESC

SELECT CAST(started_at AS DATE) AS "d", COUNT(*) AS "count", COALESCE(SUM(prompt_tokens), 0) AS "prompt", COALESCE(SUM(completion_tokens), 0) AS "completion", COALESCE(SUM(total_tokens), 0) AS "total", COALESCE(SUM(cached_tokens), 0) AS "cached", SUM(CASE WHEN status_code IS NOT NULL AND status_code >= 400 THEN 1 ELSE 0 END) AS "errors" FROM call_log WHERE 1 = 1
AND key_id = #{keyId}
AND started_at >= #{start}
AND started_at < #{end}
GROUP BY CAST(started_at AS DATE) ORDER BY "d" ASC
